  } catch { /* ok */ }
}

function makeBubbleCapture() {
  const bubbles = [];
  return {
    bubbles,
    queueSpeechBubble(opts) {
      bubbles.push(opts);
    },
  };
}

function makeWispStub() {
  let guide = false;
  return {
    setGuideMode(v) { guide = !!v; },
    get guideMode() { return guide; },
  };
}

